// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 deposit, uint256 collectAmt) public {
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);
        vm.assume(deposit > 0 && deposit <= 100 ether);
        vm.assume(collectAmt > 0 && collectAmt <= deposit);

        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit from both callers
        vm.deal(caller1, deposit);
        vm.prank(caller1);
        c.Deposit{value: deposit}();

        vm.deal(caller2, deposit);
        vm.prank(caller2);
        c.Deposit{value: deposit}();

        uint256 totalBefore = address(c).balance;

        // caller1 collects
        vm.prank(caller1);
        try c.Collect(collectAmt) {
            // success - check total balance did not increase
            uint256 totalAfter = address(c).balance;
            assertTrue(totalAfter <= totalBefore, "Total balance should not increase after Collect");
        } catch {
            // revert case - balance unchanged, so total <= totalBefore holds
            uint256 totalAfter = address(c).balance;
            assertTrue(totalAfter == totalBefore, "Total balance unchanged on revert");
        }
    }
}

