pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        depositAmount = bound(depositAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, 1e30);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount + collectAmount); // ensure enough ether for deposit and potential collect
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record state before Collect
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 contractBalanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // State after Collect
        uint256 callerBalanceAfter = c.balances(caller);
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: caller's mapping balance + contract balance stays the same (ether is conserved)
        assertTrue(callerBalanceBefore + contractBalanceBefore == callerBalanceAfter + contractBalanceAfter);
    }
}

