pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint minSum, uint amount) public {
        vm.assume(caller != address(0) && address(c).balance >= 0);
        // Set minSum so that the condition balances[caller] >= MinSum is possible
        // We'll deposit some Ether first to caller, then set MinSum
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.Deposit{value: 1 ether}();
        // Set MinSum to 0 so that the condition passes
        c.SetMinSum(0);
        c.Initialized();
        // Get the sum of balances before
        uint sumBefore = c.balances(caller);
        // Now call Collect with amount <= balances[caller]
        vm.prank(caller);
        c.Collect(0.5 ether);
        // Get sum after
        uint sumAfter = c.balances(caller);
        // The rule: the sum should not increase; it should decrease or stay same
        assertTrue(sumAfter <= sumBefore);
    }
}

