pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        // Fund caller with some ether for deposit and later gas
        vm.deal(caller, amount + 1 ether);
        // Set MinSum to 0 so Collect doesn't revert due to MinSum condition
        c.SetMinSum(0);
        c.Initialized();
        // Deposit some ether to get a positive balance
        vm.prank(caller);
        c.Deposit{value: amount}();
        uint256 beforeBalance = c.balances(caller);
        // Ensure amount is not larger than balance to avoid revert
        vm.assume(amount <= beforeBalance);
        // Execute Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));
        // If call succeeded, check balance decreased
        if (success) {
            uint256 afterBalance = c.balances(caller);
            assertTrue(afterBalance <= beforeBalance - amount, "Balance did not decrease as expected");
        } else {
            // If reverted, balance unchanged
            uint256 afterBalance = c.balances(caller);
            assertTrue(afterBalance == beforeBalance, "Balance changed on revert");
        }
    }
}

