pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint _minSum, uint _initialBalance, uint _collectAmount) public {
        // Bound values to avoid overflow
        _minSum = bound(_minSum, 0, 1e30);
        _initialBalance = bound(_initialBalance, 0, 1e30);
        _collectAmount = bound(_collectAmount, 0, 1e30);

        // Prevent zero MinSum from being set later (must set before initializing)
        vm.assume(_minSum > 0);

        c.SetMinSum(_minSum);

        // Fund the test contract to send ETH
        vm.deal(address(this), _initialBalance + _collectAmount);

        // Deposit initial balance
        (bool successDeposit,) = address(c).call{value: _initialBalance}("");
        require(successDeposit, "Deposit failed");

        // Initialize contract
        c.Initialized();

        uint balanceBefore = c.balances(address(this));
        bool conditionMetBeforeCollect = (balanceBefore >= _minSum);

        // Call Collect
        (bool successCollect,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _collectAmount));

        uint balanceAfter = c.balances(address(this));

        // Rule: if condition was met (balance >= MinSum and balance >= amount), 
        // balance decreases by exactly amount; otherwise balance unchanged
        if (conditionMetBeforeCollect && balanceBefore >= _collectAmount) {
            assertTrue(balanceAfter == balanceBefore - _collectAmount, "Balance should decrease by collected amount");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged");
        }
    }
}

