pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 minSum, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(deposit >= 1e9); // avoid overflow; we need meaningful values
        vm.assume(amount > 0 && amount <= deposit);
        // Initialize contract and set MinSum
        c.SetMinSum(minSum);
        c.Initialized();
        // Fund the caller and deposit into contract
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();
        // Record caller's balance before Collect
        uint256 balBefore = c.balances(caller);
        // Perform Collect
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));
        // After Collect, check the invariant: if the caller's balance decreased, then before the call it must have been >= MinSum
        uint256 balAfter = c.balances(caller);
        if (!ok) {
            // If it reverted, balance should be unchanged
            assertTrue(balAfter == balBefore);
        } else {
            // If it succeeded, balance decreased
            if (balAfter < balBefore) {
                // The reference requires that the caller's balance BEFORE call was >= MinSum
                assertTrue(balBefore >= minSum);
            } else {
                // If balance didn't decrease, it means the condition wasn't met
                assertTrue(balBefore < minSum || balBefore < amount);
            }
        }
    }
}

