pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit0, uint256 deposit1, uint256 collectAm, address user1, address user2) public {
        // Set MinSum to a value that doesn't allow collect until we deposit enough
        vm.assume(deposit0 < type(uint256).max / 2);
        vm.assume(deposit1 < type(uint256).max / 2);
        vm.assume(collectAm <= deposit0 + deposit1);
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);

        // Initialize the contract
        c.SetMinSum(0); // Allow collect with any positive balance
        c.SetLogFile(address(12345)); // dummy log file
        c.Initialized();

        // Track total incoming ETH
        uint256 totalIn = 0;

        // User1 deposits
        vm.deal(user1, deposit0);
        vm.prank(user1);
        c.Deposit{value: deposit0}();
        totalIn += deposit0;

        // User2 deposits
        vm.deal(user2, deposit1);
        vm.prank(user2);
        c.Deposit{value: deposit1}();
        totalIn += deposit1;

        // User1 collects
        vm.prank(user1);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, collectAm));

        // Check the invariant: total ETH in contract plus all balances equals total deposited
        uint256 contractBalance = address(c).balance;
        uint256 sumBalances = c.balances(user1) + c.balances(user2);

        assertTrue(contractBalance + sumBalances == totalIn);
    }
}

