pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit amount to avoid overflow (which would revert anyway)
        vm.assume(depositAmount < type(uint256).max / 2);
        vm.assume(user != address(0));

        // Setup: initialize contract and set log file to avoid revert
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Deposit some funds
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Record balance before withdrawal
        uint256 balBefore = c.balances(user);

        // Withdraw if possible, else skip (withdrawAmount must be <= balance and >= MinSum=0)
        vm.assume(withdrawAmount <= balBefore && withdrawAmount >= 0);

        vm.prank(user);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // If the call succeeded (which it will when balances[user] >= MinSum and _am <= balances[user])
        if (ok) {
            uint256 balAfter = c.balances(user);
            // General rule: balance decreases by exactly the withdrawn amount
            assertTrue(balAfter == balBefore - withdrawAmount);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

