import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow and ensure sufficient balance
        vm.assume(caller != address(0));
        minSum = bound(minSum, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Setup: set MinSum and initialize
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit funds from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Collect (will succeed if balances[caller] >= MinSum and balances[caller] >= collectAmount)
        uint256 balanceBefore = address(caller).balance;
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        // Decode revert if any; we consider only successful calls
        if (success && c.balances(caller) >= minSum && c.balances(caller) >= collectAmount) {
            // After successful call, MinSum should be the original set value, not zero (if minSum != 0)
            // The bug sets MinSum = 0 in SetMinSum, so we assert MinSum != 0 if we set it non-zero
            // But we need a general rule: the MinSum state after all operations equals the value passed to SetMinSum
            // However, Initialized() disallows further SetMinSum calls, so MinSum should remain minSum
            assertTrue(c.MinSum() == minSum, "MinSum changed after Collect");
        }
    }
}

