                // In reference, Collect should succeed only if balanceBefore >= withdrawAmount
                assertTrue(success, "Collect should succeed when sufficient balance");
                // After success, balance should decrease by withdrawAmount
                assertEq(balanceAfter, balanceBefore - withdrawAmount);
            } else {
                // When withdrawAmount > balanceBefore, reference reverts or does nothing
                // The balance should not change
                assertTrue(!success || balanceAfter == balanceBefore, "Collect should not decrease balance when overdraw");
            }
        } else {
            // If balance < minSum, Collect does nothing (condition fails)
            assertTrue(!success || balanceAfter == balanceBefore, "Collect should not change balance when below minSum");
        }
    }
}

