pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to avoid overflow and ensure realistic values
        initialBalance = bound(initialBalance, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);
        withdrawAmount = bound(withdrawAmount, 0, 1e30);

        // Ensure the total deposit does not overflow the state variable
        vm.assume(initialBalance + depositAmount > initialBalance);
        vm.assume(withdrawAmount <= initialBalance + depositAmount);

        // Setup: fund the contract and set MinSum to 0 so Collect can proceed
        c.SetMinSum(0);
        c.Initialized();

        // Fund a random address
        address user = address(0x1234);
        vm.deal(user, initialBalance + depositAmount);
        vm.prank(user);
        (bool ok,) = address(c).call{value: depositAmount}("");
        vm.assume(ok);

        // Record balance before Collect
        uint256 balanceBefore = c.balances(user);

        // Execute Collect
        vm.prank(user);
        c.Collect(withdrawAmount);

        uint256 balanceAfter = c.balances(user);

        // General rule: if Collect succeeded (balance decreased), then the deduction equals withdrawAmount
        // If withdrawAmount > balanceBefore, Collect should have failed and balance unchanged
        if (balanceAfter < balanceBefore) {
            assertTrue(balanceBefore - balanceAfter == withdrawAmount, "Withdraw amount not correctly subtracted");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should not change if withdraw failed");
        }
    }
}
